// Map service titles and aliases to canonical service keys
export function resolveServiceKey(keyOrTitle: string): string {
  const lower = (keyOrTitle || '').toLowerCase().trim();
  
  if (allServiceVoiceTexts[keyOrTitle]) return keyOrTitle;
  if (allServiceVoiceTexts[lower]) return lower;

  // BBingo / Bingo aliases
  if (lower.includes('bbingo') || lower.includes('bingo') || lower.includes('बीबींगो') || lower.includes('बिंगो') || lower.includes('bibingo') || lower.includes('b-bingo')) {
    return 'bbingo';
  }

  // Agreements & Affidavits aliases
  if (lower.includes('rent') || lower.includes('lease') || lower.includes('tenancy') || lower.includes('किराया')) {
    return 'rent_agreement';
  }
  if (lower.includes('noc') || lower.includes('एनओसी') || lower.includes('objection')) {
    return 'landlord_noc';
  }
  if (lower.includes('affidavit') || lower.includes('शपथपत्र') || lower.includes('name change') || lower.includes('loss of document')) {
    return 'affidavit';
  }

  if (lower.includes('gst reg') || (lower.includes('gst') && (lower.includes('registration') || lower.includes('नोंदणी') || lower.includes('રજીસ્ટ્રેશન') || lower.includes('രജിസ്ട്രേഷൻ') || lower.includes('பதிவு') || lower.includes('ਰਜਿਸਟਰੇਸ਼ਨ') || lower.includes('రిజిస్ట్రేషన్') || lower.includes('রেজিস্ট্রেশন') || lower.includes('ನೋಂದಣಿ')))) {
    return 'gst_registration';
  }
  if (lower.includes('udyam') || lower.includes('msme') || lower.includes('उद्यम') || lower.includes('ಉದ್ಯಮ್') || lower.includes('உத்யோகம்')) {
    return 'udyam_registration';
  }
  if (lower.includes('pvt') || lower.includes('private limited') || lower.includes('प्राइवेट') || lower.includes('પ્રાઇવેટ') || lower.includes('പ്രൈവറ്റ്') || lower.includes('பிரைவேட்') || lower.includes('ਪ੍ਰਾਈਵੇਟ') || lower.includes('ప్రైవేట్') || lower.includes('ಪ್ರೈವೇಟ್')) {
    return 'pvt_ltd';
  }
  if (lower.includes('llp') || lower.includes('liability partnership') || lower.includes('एलएलपी') || lower.includes('એલએલપી') || lower.includes('ಎಲ್ಎಲ್ಪಿ') || lower.includes('எல்எல்பி')) {
    return 'llp';
  }
  if (lower.includes('trademark') || lower.includes('ट्रेडमार्क') || lower.includes('ટ્રેડમાર્ક') || lower.includes('ട്രാഡ്മാർക്ക്') || lower.includes('ಟ್ರೇಡ್‌ಮಾರ್ಕ್') || lower.includes('வர்த்தக')) {
    return 'trademark';
  }
  if (lower.includes('fssai') || lower.includes('food') || lower.includes('एफएसएसएआई') || lower.includes('એફએસએસએઆઈ')) {
    return 'fssai';
  }
  if (lower.includes('car') || lower.includes('कार') || lower.includes('કાર્') || lower.includes('കാർ') || lower.includes('கார்') || lower.includes('ಕಾರ್')) {
    return 'car_insurance';
  }
  if (lower.includes('bike') || lower.includes('two wheeler') || lower.includes('बाइक') || lower.includes('बाईक') || lower.includes('બાઇક') || lower.includes('ബൈക്ക്') || lower.includes('பைக்') || lower.includes('బైక్') || lower.includes('ಬೈಕ್')) {
    return 'bike_insurance';
  }
  if (lower.includes('truck') || lower.includes('commercial vehicle') || lower.includes('ट्रक') || lower.includes('ટ્રક') || lower.includes('ട്രക്ക്') || lower.includes('லாரி') || lower.includes('ట్రక్') || lower.includes('ಟ್ರಕ್')) {
    return 'truck_insurance';
  }
  if (lower.includes('misc') || lower.includes('miscellaneous') || lower.includes('मिसलेनियस')) {
    return 'misc_insurance';
  }
  if (lower.includes('other insurance') || (lower.includes('insurance') && lower.includes('other')) || lower.includes('इतर विमा') || lower.includes('અન્ય ઇન્શ્યોરન્સ')) {
    return 'other_insurance';
  }
  if (lower.includes('gst filing') || (lower.includes('gst') && (lower.includes('filing') || lower.includes('फाइलिंग') || lower.includes('ફાઇલિંગ')))) {
    return 'gst_filing';
  }
  if (lower.includes('income tax') || lower.includes('itr') || lower.includes('आयकर') || lower.includes('ઇન્કમ ટેક્સ') || lower.includes('ആദായ നികുതി')) {
    return 'income_tax_filing';
  }
  if (lower.includes('other filing') || (lower.includes('filing') && lower.includes('other')) || lower.includes('इतर फायलिंग') || lower.includes('અન્ય ફાઇલિંગ')) {
    return 'other_filing';
  }

  // Default fallback to first service key
  return 'gst_registration';
}

// 2. NATIVE NATURAL SPEECH SYNTHESIS ENGINE (Edge / Google / Native TTS)
// Crisp, fast, energetic pronunciation without stutter or proxy delays

export const VOICE_LANGUAGE_TAGS: Record<VoiceLanguageCode, string> = {
  hi: 'hi-IN',
  en: 'en-IN',
  mr: 'mr-IN',
  gu: 'gu-IN',
  pa: 'pa-IN',
  ml: 'ml-IN',
  ta: 'ta-IN',
  te: 'te-IN',
  bn: 'bn-IN',
  kn: 'kn-IN'
};

// Exported for backward compatibility with existing code
export let currentAudioPlayer: HTMLAudioElement | null = null;
let currentPlayingServiceKey: string | null = null;
let currentUtterance: SpeechSynthesisUtterance | null = null;
let speechHeartbeatTimer: any = null;

type VoiceListener = (isPlaying: boolean, serviceKey: string | null) => void;
const listeners = new Set<VoiceListener>();

function notifyListeners() {
  const isSpeaking = Boolean(
    (typeof window !== 'undefined' && 'speechSynthesis' in window && window.speechSynthesis.speaking) ||
    (currentAudioPlayer && !currentAudioPlayer.paused) ||
    currentPlayingServiceKey !== null
  );
  listeners.forEach((listener) => {
    try {
      listener(isSpeaking, isSpeaking ? currentPlayingServiceKey : null);
    } catch (e) {
      console.warn('Voice listener error:', e);
    }
  });
}

export function subscribeVoiceState(listener: VoiceListener): () => void {
  listeners.add(listener);
  const isSpeaking = Boolean(
    (typeof window !== 'undefined' && 'speechSynthesis' in window && window.speechSynthesis.speaking) ||
    (currentAudioPlayer && !currentAudioPlayer.paused) ||
    currentPlayingServiceKey !== null
  );
  listener(isSpeaking, currentPlayingServiceKey);
  return () => {
    listeners.delete(listener);
  };
}

export function isServiceVoicePlaying(serviceKey?: string): boolean {
  const isSpeaking = Boolean(
    (typeof window !== 'undefined' && 'speechSynthesis' in window && window.speechSynthesis.speaking) ||
    (currentAudioPlayer && !currentAudioPlayer.paused) ||
    currentPlayingServiceKey !== null
  );
  if (!isSpeaking) return false;
  if (!serviceKey) return true;
  return resolveServiceKey(serviceKey) === currentPlayingServiceKey;
}

/**
 * 1 & 2. Voice resolution with instant fallback:
 * Requested language -> Hindi ('hi-IN') -> Indian English ('en-IN') -> Default voice
 */
function resolveVoiceAndLanguage(langCode: VoiceLanguageCode): { voice: SpeechSynthesisVoice | null; lang: string } {
  if (typeof window === 'undefined' || !('speechSynthesis' in window)) {
    return { voice: null, lang: 'hi-IN' };
  }

  const voices = window.speechSynthesis.getVoices() || [];
  const requestedTag = VOICE_LANGUAGE_TAGS[langCode] || 'hi-IN';

  if (voices.length > 0) {
    // 1. Try to find a voice for requested language
    const exactVoice = voices.find((v) => {
      const vLang = v.lang.replace('_', '-').toLowerCase();
      return vLang === requestedTag.toLowerCase();
    });
    if (exactVoice) {
      console.log(`[VoiceGuidance] Found exact voice for '${requestedTag}':`, exactVoice.name);
      return { voice: exactVoice, lang: exactVoice.lang };
    }

    const prefixVoice = voices.find((v) => {
      const vLang = v.lang.replace('_', '-').toLowerCase();
      return vLang.startsWith(langCode.toLowerCase());
    });
    if (prefixVoice) {
      console.log(`[VoiceGuidance] Found prefix voice for '${langCode}':`, prefixVoice.name);
      return { voice: prefixVoice, lang: prefixVoice.lang };
    }

    // 2. Fallback to Hindi ('hi-IN') if regional voice is not on device
    const hindiVoice = voices.find((v) => {
      const vLang = v.lang.replace('_', '-').toLowerCase();
      return vLang === 'hi-in' || vLang.startsWith('hi');
    });
    if (hindiVoice) {
      console.log(`[VoiceGuidance] No voice on device for '${requestedTag}'. Falling back to Hindi:`, hindiVoice.name);
      return { voice: hindiVoice, lang: 'hi-IN' };
    }

    // 3. Fallback to Indian English ('en-IN') or any English voice
    const englishVoice = voices.find((v) => {
      const vLang = v.lang.replace('_', '-').toLowerCase();
      return vLang === 'en-in' || vLang.startsWith('en');
    });
    if (englishVoice) {
      console.log(`[VoiceGuidance] Falling back to English voice:`, englishVoice.name);
      return { voice: englishVoice, lang: 'en-IN' };
    }

    // 4. Fallback to default system voice
    const defaultVoice = voices.find((v) => v.default) || voices[0];
    if (defaultVoice) {
      console.log(`[VoiceGuidance] Falling back to default system voice:`, defaultVoice.name);
      return { voice: defaultVoice, lang: defaultVoice.lang || 'hi-IN' };
    }
  }

  // If voices list is still empty, safe fallback to hi-IN
  return { voice: null, lang: 'hi-IN' };
}

// Pre-warm browser voices on page load
if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
  try {
    window.speechSynthesis.getVoices();
    window.speechSynthesis.onvoiceschanged = () => {
      const voices = window.speechSynthesis.getVoices();
      console.log('[VoiceGuidance] Speech voices loaded into browser:', voices.length);
    };
  } catch {}
}

// Active play session tracking to ensure ONLY ONE voice can ever play at any instant
let currentPlaySessionId = 0;

/**
 * 4. MUTE / STOP CONTROLS:
 * Stops any playing speech or audio immediately
 */
export function stopServiceVoice() {
  currentPlaySessionId++;
  if (speechHeartbeatTimer) {
    clearInterval(speechHeartbeatTimer);
    speechHeartbeatTimer = null;
  }
  if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
    try {
      window.speechSynthesis.cancel();
    } catch {}
  }
  if (currentAudioPlayer) {
    try {
      currentAudioPlayer.pause();
      currentAudioPlayer.currentTime = 0;
      currentAudioPlayer.src = '';
    } catch {}
    currentAudioPlayer = null;
  }
  currentPlayingServiceKey = null;
  notifyListeners();
}

/**
 * Plays the voice guidance for the requested service using native SpeechSynthesis
 * With energetic 1.5x speed, accurate pronunciation, and seamless delivery
 */
export function playServiceVoice(serviceKey: string) {
  // 1. Mandatory cancel before speaking
  stopServiceVoice();
  if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
    try {
      window.speechSynthesis.cancel();
    } catch {}
  }

  const thisSession = ++currentPlaySessionId;
  const canonicalKey = resolveServiceKey(serviceKey);
  const userLang = (localStorage.getItem('userAudioLanguage') || localStorage.getItem('ctc_audio_language_v2') || 'hi') as VoiceLanguageCode;
  const bcp47 = VOICE_LANGUAGE_TAGS[userLang] || 'hi-IN';

  console.log('[VoiceGuidance] Service Button Clicked (Session #' + thisSession + '):', {
    serviceKey,
    canonicalKey,
    userAudioLanguage: userLang,
    bcp47
  });

  const serviceData = allServiceVoiceTexts[canonicalKey] || allServiceVoiceTexts['gst_registration'];
  const rawText = serviceData[userLang] || serviceData['hi'] || '';

  if (!rawText) {
    console.warn('[VoiceGuidance] No voice text found for serviceKey:', serviceKey, 'lang:', userLang);
    return;
  }

  // Sanitize text for crisp, fluid speech without awkward pauses
  const textToSpeak = rawText
    .replace(/["'“”]/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  if (typeof window === 'undefined' || !('speechSynthesis' in window) || typeof SpeechSynthesisUtterance === 'undefined') {
    console.warn('[VoiceGuidance] window.speechSynthesis not supported on this browser.');
    return;
  }

  try {
    if (window.speechSynthesis.paused) {
      window.speechSynthesis.resume();
    }

    const { voice, lang } = resolveVoiceAndLanguage(userLang);

    // 1. GARBAGE COLLECTION FIX: Attach to window.currentUtterance so the browser GC never destroys it
    const utterance = new SpeechSynthesisUtterance(textToSpeak);
    currentUtterance = utterance;
    if (typeof window !== 'undefined') {
      (window as any).currentUtterance = utterance;
    }

    utterance.lang = lang;
    utterance.rate = 1.5;
    utterance.pitch = 1.02;

    if (voice) {
      utterance.voice = voice;
      console.log('[VoiceGuidance] Assigned Voice:', voice.name, `(${voice.lang})`);
    } else {
      console.log('[VoiceGuidance] Using default browser voice for lang:', lang);
    }

    // 3. EVENT LISTENERS with detailed console logs
    utterance.onstart = () => {
      if (thisSession !== currentPlaySessionId) {
        if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
          try { window.speechSynthesis.cancel(); } catch {}
        }
        return;
      }
      console.log('🔊 [VoiceGuidance] SPEECH ONSTART: Started speaking successfully for:', canonicalKey, '| Lang:', utterance.lang, '| Rate:', utterance.rate);
      currentPlayingServiceKey = canonicalKey;
      notifyListeners();

      // Chrome/Safari speech timeout workaround (prevents mid-sentence cutoff)
      if (speechHeartbeatTimer) clearInterval(speechHeartbeatTimer);
      speechHeartbeatTimer = setInterval(() => {
        if (thisSession !== currentPlaySessionId) {
          if (speechHeartbeatTimer) {
            clearInterval(speechHeartbeatTimer);
            speechHeartbeatTimer = null;
          }
          return;
        }
        if (typeof window !== 'undefined' && 'speechSynthesis' in window && window.speechSynthesis.speaking) {
          window.speechSynthesis.resume();
        } else {
          if (speechHeartbeatTimer) {
            clearInterval(speechHeartbeatTimer);
            speechHeartbeatTimer = null;
          }
        }
      }, 3000);
    };

    utterance.onend = () => {
      if (thisSession !== currentPlaySessionId) return;
      console.log('✅ [VoiceGuidance] SPEECH ONEND: Finished speaking naturally for:', canonicalKey);
      stopServiceVoice();
    };

    utterance.onerror = (e) => {
      if (thisSession !== currentPlaySessionId) return;
      console.error('❌ [VoiceGuidance] SPEECH ONERROR (error event):', e.error || e, e);
      stopServiceVoice();
    };

    // 2. IMMEDIATE USER GESTURE EXECUTION: Speak instantly upon click without setTimeout delay
    try {
      if (window.speechSynthesis.paused) {
        window.speechSynthesis.resume();
      }
      console.log('🔊 [VoiceGuidance] Calling window.speechSynthesis.speak() immediately on click for session #' + thisSession);
      window.speechSynthesis.speak(utterance);
      currentPlayingServiceKey = canonicalKey;
      notifyListeners();

      // Ensure speech engine does not remain in paused state
      if (window.speechSynthesis.paused) {
        window.speechSynthesis.resume();
      }
    } catch (speakErr) {
      console.error('[VoiceGuidance] Exception executing speak():', speakErr);
      stopServiceVoice();
    }
  } catch (err) {
    console.error('[VoiceGuidance] Exception setting up speech:', err);
    stopServiceVoice();
  }
}

/**
 * Toggle voice playback for a service
 */
export function toggleServiceVoice(serviceKey: string) {
  const canonicalKey = resolveServiceKey(serviceKey);
  if (isServiceVoicePlaying(canonicalKey)) {
    stopServiceVoice();
  } else {
    playServiceVoice(canonicalKey);
  }
}

// Expose on window object for direct HTML / script consumption as requested
if (typeof window !== 'undefined') {
  (window as any).allServiceVoiceTexts = allServiceVoiceTexts;
  (window as any).playServiceVoice = playServiceVoice;
  (window as any).stopServiceVoice = stopServiceVoice;
  (window as any).toggleServiceVoice = toggleServiceVoice;
}
